import { expect, test } from "@playwright/test";

/**
 * Guards the auth-boundary lifecycle of local questionnaire fill drafts
 * (`src/components/QuestionnaireV2/fill/draft/fillDraftCache.ts`):
 *
 * - A draft sitting at the login form (e.g. left behind by a session
 *   expiry) must survive a mistyped password — it is recoverable work,
 *   not something a failed login attempt should destroy.
 * - Credentials being ACCEPTED clears every OTHER user's draft
 *   (`clearOtherUsersFillDrafts`, wired into the JWT sign-in success branch
 *   in `AuthUserProvider.tsx`) — a shared machine gets a clean slate for a
 *   different account — but the just-authenticated user's OWN draft
 *   survives: that is the crash/session-expiry recovery this feature
 *   exists for, not something re-login should destroy.
 * - The boot-time sweep (`sweepExpiredFillDrafts`) only removes EXPIRED
 *   drafts, so fresh drafts seeded right before the app mounts must still
 *   be there after boot — the eventual disappearance of the OTHER-user
 *   draft is attributable to the post-auth clear, not the sweep.
 *
 * Matches the shape `fillDraftStore.ts` writes to localStorage — see
 * `draftKey()` / `StoredFillDraft` there — and the userId-prefix parsing
 * `clearOtherUsersFillDrafts` does in `fillDraftCache.ts`.
 */
const FILL_DRAFT_PREFIX = "care_qn_fill_draft--";
// src/common/constants.tsx LocalStorageKeys — tests can't import "@/*"
// (tests/tsconfig.json's "paths" only maps "tests/*", it doesn't inherit
// the app's aliases), so the raw key strings are duplicated here.
const ACCESS_TOKEN_KEY = "care_access_token";
const REFRESH_TOKEN_KEY = "care_refresh_token";

const OTHER_USER_DRAFT_KEY = `${FILL_DRAFT_PREFIX}some-other-user--some-patient--some-questionnaire`;

/**
 * Post-login landing: any URL that is no longer the login page. A
 * predicate, not a regex — the negative-lookahead idiom (`/(?!.*login)/`)
 * matches EVERY url (the lookahead succeeds at the end of the string), so
 * it waits for nothing at all, and this test strips the tokens the moment
 * the wait returns.
 */
function loggedInUrl(url: URL): boolean {
  return !url.pathname.startsWith("/login");
}

function draftKeyFor(userId: string): string {
  return `${FILL_DRAFT_PREFIX}${userId}--some-patient--some-questionnaire`;
}

function buildSeededDraft(userId: string) {
  return {
    schemaVersion: 2,
    // Fresh timestamp — well inside the 24h TTL — so the boot sweep must
    // not treat this as expired.
    savedAt: new Date().toISOString(),
    userId,
    subjectKey: "some-patient",
    entryQuestionnaireId: "some-questionnaire",
    forms: [
      {
        questionnaireId: "some-questionnaire",
        questionnaireVersion: "1",
        title: "Seeded draft for auth-boundary spec",
        responses: {},
        structuredSkipped: false,
      },
    ],
  };
}

test.describe("Fill draft lifecycle at the login form", () => {
  // One test, deliberately sequential: discovering the real admin user id
  // (needed to seed a same-user draft correctly) requires an ordinary
  // login first, so id discovery and the actual scenario cannot be split
  // into independent `test()` blocks without either re-authenticating twice
  // or hardcoding a backend-specific id. A single test keeps that dependency
  // explicit instead of hiding it behind Playwright's test-level parallelism.
  test("an other-user draft is cleared on successful login; a failed login and the same user's own draft both survive", async ({
    page,
  }) => {
    // Discover the real authenticated user id.
    // `clearOtherUsersFillDrafts` is keyed off `CurrentUserRead.id` (the
    // same value `QuestionnaireFillPage` uses as `FillDraftScope.userId`),
    // not the JWT's own `user_id` claim — the two are not guaranteed to be
    // the same value, so this test reads it straight from the app's own
    // `getcurrentuser` response rather than assume a token-decoding shortcut.
    await page.goto("/login");
    const currentUserResponsePromise = page.waitForResponse(
      (res) => res.url().includes("/getcurrentuser/") && res.ok(),
    );
    await page.getByRole("textbox", { name: /username/i }).fill("admin");
    await page.getByLabel(/password/i).fill("admin");
    await page.getByRole("button", { name: /login/i }).click();
    const currentUserResponse = await currentUserResponsePromise;
    const { id: adminUserId } = (await currentUserResponse.json()) as {
      id: string;
    };
    expect(adminUserId).toBeTruthy();
    await page.waitForURL(loggedInUrl, { timeout: 15000 });

    // Drop back to a logged-out /login without going through the sign-out
    // UI: signOut() does a full, unconditional draft clear (unchanged by
    // this feature and not what this test is about), and this test hasn't
    // seeded anything yet for it to destroy. Directly clearing the tokens
    // is equivalent from the boot sweep's/clear's perspective — both only
    // ever read localStorage, never React/query state.
    await page.evaluate(
      ({ accessKey, refreshKey }) => {
        localStorage.removeItem(accessKey);
        localStorage.removeItem(refreshKey);
      },
      { accessKey: ACCESS_TOKEN_KEY, refreshKey: REFRESH_TOKEN_KEY },
    );

    // Seed one other-user draft and one same-user draft.
    const sameUserDraftKey = draftKeyFor(adminUserId);
    await page.addInitScript(
      ({ otherKey, otherValue, sameKey, sameValue }) => {
        localStorage.setItem(otherKey, JSON.stringify(otherValue));
        localStorage.setItem(sameKey, JSON.stringify(sameValue));
      },
      {
        otherKey: OTHER_USER_DRAFT_KEY,
        otherValue: buildSeededDraft("some-other-user"),
        sameKey: sameUserDraftKey,
        sameValue: buildSeededDraft(adminUserId),
      },
    );

    await page.goto("/login");

    // Sanity: the boot sweep ran (AuthUserProvider mounts on every route)
    // and left both fresh drafts alone.
    await expect
      .poll(() =>
        page.evaluate((key) => localStorage.getItem(key), OTHER_USER_DRAFT_KEY),
      )
      .not.toBeNull();
    expect(
      await page.evaluate((key) => localStorage.getItem(key), sameUserDraftKey),
    ).not.toBeNull();

    // A mistyped password must not touch either draft.
    await page.getByRole("textbox", { name: /username/i }).fill("admin");
    await page.getByLabel(/password/i).fill("wrongpassword");
    await page.getByRole("button", { name: /login/i }).click();
    await expect(page.getByText(/no active account found/i)).toBeVisible({
      timeout: 10000,
    });

    expect(
      await page.evaluate(
        (key) => localStorage.getItem(key),
        OTHER_USER_DRAFT_KEY,
      ),
    ).not.toBeNull();
    expect(
      await page.evaluate((key) => localStorage.getItem(key), sameUserDraftKey),
    ).not.toBeNull();

    // Sign in correctly as the same user.
    await page.getByLabel(/password/i).fill("admin");
    await page.getByRole("button", { name: /login/i }).click();
    await page.waitForURL(loggedInUrl, { timeout: 15000 });
    await expect(page.getByRole("heading", { name: /^Hey .+/ })).toBeVisible();

    // The OTHER user's draft is gone — cleared as soon as credentials were
    // accepted.
    await expect
      .poll(() =>
        page.evaluate((key) => localStorage.getItem(key), OTHER_USER_DRAFT_KEY),
      )
      .toBeNull();

    // The SAME user's own draft survived re-login — recovering it is the
    // whole point of the local draft layer.
    expect(
      await page.evaluate((key) => localStorage.getItem(key), sameUserDraftKey),
    ).not.toBeNull();
  });
});
import { useQuery } from "@tanstack/react-query";
import { navigate, usePath } from "raviger";
import {
  createContext,
  useCallback,
  useEffect,
  useMemo,
  useState,
} from "react";

import { LocalStorageKeys } from "@/common/constants";

import { useAuthContext } from "@/hooks/useAuthUser";

import query from "@/Utils/request/query";
import { PublicPatientRead } from "@/types/emr/patient/patient";
import publicPatientApi from "@/types/emr/patient/publicPatientApi";
import { TokenData } from "@/types/otp/otp";

export type PatientUserContextType = {
  patients?: PublicPatientRead[];
  selectedPatient: PublicPatientRead | null;
  setSelectedPatient: (patient: PublicPatientRead) => void;
  isLoadingPatients: boolean;
  tokenData: TokenData;
};

export const PatientUserContext = createContext<PatientUserContextType | null>(
  null,
);

const APPOINTMENT_REGISTRATION_PATH_REGEX =
  /^\/facility\/[^/]+\/appointments\/[^/]+\/patient-registration$/;

interface Props {
  children: React.ReactNode;
}

export default function PatientUserProvider({ children }: Props) {
  const [selectedPatientId, setSelectedPatientId] = useState<string | null>(
    () => localStorage.getItem(LocalStorageKeys.selectedPatient),
  );
  const path = usePath();

  const { patientToken: tokenData } = useAuthContext();

  const { data: userData, isLoading } = useQuery({
    queryKey: ["patients", tokenData],
    queryFn: query(publicPatientApi.list, {
      headers: {
        Authorization: `Bearer ${tokenData?.token}`,
      },
    }),
    enabled: !!tokenData?.token,
  });

  const patients = useMemo(() => userData?.results ?? [], [userData]);

  // A stored id can go stale (profile unlinked, or a different number signed
  // in), so resolution always falls back to the first linked profile. The
  // stored value is only rewritten on an explicit switch.
  const selectedPatient = useMemo(
    () =>
      patients.find((patient) => patient.id === selectedPatientId) ??
      patients[0] ??
      null,
    [patients, selectedPatientId],
  );

  const setSelectedPatient = useCallback((patient: PublicPatientRead) => {
    setSelectedPatientId(patient.id);
    localStorage.setItem(LocalStorageKeys.selectedPatient, patient.id);
  }, []);

  // Every screen under this provider needs a patient session, so send an
  // unauthenticated (or signed-out) visitor to the patient login rather than
  // the public landing page.
  useEffect(() => {
    if (!tokenData) {
      navigate("/patient/login", { replace: true });
    }
  }, [tokenData]);

  const isProfileSetupPath =
    path === "/patient/select-profile" ||
    path === "/patient/add-profile" ||
    APPOINTMENT_REGISTRATION_PATH_REGEX.test(path || "");

  useEffect(() => {
    if (
      tokenData &&
      !isLoading &&
      patients.length === 0 &&
      !isProfileSetupPath
    ) {
      navigate("/patient/select-profile", { replace: true });
    }
  }, [tokenData, isLoading, patients.length, isProfileSetupPath]);

  if (!tokenData) {
    return null;
  }

  return (
    <PatientUserContext.Provider
      value={{
        patients,
        selectedPatient,
        setSelectedPatient,
        isLoadingPatients: isLoading,
        tokenData,
      }}
    >
      {children}
    </PatientUserContext.Provider>
  );
}
import { Redirect, useRoutes } from "raviger";

import ErrorBoundary from "@/components/Common/ErrorBoundary";
import BrowserWarning from "@/components/ErrorPages/BrowserWarning";
import ErrorPage from "@/components/ErrorPages/DefaultErrorPage";

import PatientUserProvider from "@/Providers/PatientUserProvider";
import DiagnosticReportDetail from "@/pages/Patient/DiagnosticReportDetail";
import PatientProfileSettings from "@/pages/Patient/PatientProfileSettings";
import PatientRecords from "@/pages/Patient/PatientRecords";
import PatientVisits from "@/pages/Patient/PatientVisits";
import PrescriptionDetail from "@/pages/Patient/PrescriptionDetail";
import SelectProfile from "@/pages/Patient/SelectProfile";
import VisitSummary from "@/pages/Patient/VisitSummary";
import PatientIndex from "@/pages/Patient/index";
import BookFacility from "@/pages/PublicAppointments/BookFacility";
import BookPractitioner from "@/pages/PublicAppointments/BookPractitioner";
import PublicPatientRegistration from "@/pages/PublicAppointments/PatientRegistration";
import { ScheduleAppointment } from "@/pages/PublicAppointments/Schedule";
import { AppointmentSuccess } from "@/pages/PublicAppointments/Success";

import PublicRouter from "./PublicRouter";

/** Routes available to a patient signed in with an OTP session. */
const DashboardRoutes = {
  "/nearby_facilities": () => <BookFacility />,
  "/facility/:facilityId/appointments/:appointmentId/success": ({
    appointmentId,
  }: {
    appointmentId: string;
  }) => <AppointmentSuccess appointmentId={appointmentId} />,

  "/patient/select-profile": () => <SelectProfile />,
  "/patient/add-profile": () => <PublicPatientRegistration />,
  "/patient/home": () => <PatientIndex />,

  "/patient/visits": () => <PatientVisits />,
  "/patient/visits/:appointmentId": ({
    appointmentId,
  }: {
    appointmentId: string;
  }) => <VisitSummary appointmentId={appointmentId} />,

  "/patient/profile": () => <PatientProfileSettings />,

  "/patient/book/:facilityId": ({ facilityId }: { facilityId: string }) => (
    <BookPractitioner facilityId={facilityId} />
  ),

  "/patient/records": () => <PatientRecords />,
  "/patient/records/prescriptions/:id": ({ id }: { id: string }) => (
    <PrescriptionDetail id={id} />
  ),
  "/patient/records/reports/:id": ({ id }: { id: string }) => (
    <DiagnosticReportDetail id={id} />
  ),

  // Superseded by the records hub; kept so existing links keep working.
  "/patient/medications": () => (
    <Redirect to="/patient/records" query={{ tab: "prescriptions" }} />
  ),
  "/patient/diagnostic_reports": () => (
    <Redirect to="/patient/records" query={{ tab: "reports" }} />
  ),

  // `/patient/:id` is deliberately NOT routed here. PatientProfile is a
  // staff-facing component backed by authenticated facility APIs, so under an
  // OTP session it only ever rendered an error page — and its wildcard swallowed
  // unmatched paths like `/patient/profile`. The staff app serves those routes
  // through AppRouter (src/Routers/routes/PatientRoutes.tsx) instead.
};

const AppointmentRoutes = {
  "/facility/:facilityId/appointments/:staffId/book-appointment": ({
    facilityId,
    staffId,
  }: {
    facilityId: string;
    staffId: string;
  }) => <ScheduleAppointment facilityId={facilityId} staffId={staffId} />,
  "/facility/:facilityId/appointments/:staffId/reschedule/:appointmentId": ({
    facilityId,
    staffId,
    appointmentId,
  }: {
    facilityId: string;
    staffId: string;
    appointmentId: string;
  }) => (
    <ScheduleAppointment
      facilityId={facilityId}
      staffId={staffId}
      appointmentId={appointmentId}
    />
  ),
  "/facility/:facilityId/appointments/:staffId/patient-registration": ({
    facilityId,
    staffId,
  }: {
    facilityId: string;
    staffId: string;
  }) => <PublicPatientRegistration facilityId={facilityId} staffId={staffId} />,
};

export default function PatientRouter() {
  const pages = useRoutes(DashboardRoutes);

  const appointmentPages = useRoutes(AppointmentRoutes);

  if (!pages) {
    if (appointmentPages) {
      return (
        <PatientUserProvider>
          <ErrorBoundary fallback={<ErrorPage forError="PAGE_LOAD_ERROR" />}>
            {appointmentPages}
          </ErrorBoundary>
        </PatientUserProvider>
      );
    }
    return <PublicRouter />;
  }

  // Each patient page owns its own chrome via PatientAppShell.
  return (
    <PatientUserProvider>
      <BrowserWarning />
      <ErrorBoundary fallback={<ErrorPage forError="PAGE_LOAD_ERROR" />}>
        {pages}
      </ErrorBoundary>
    </PatientUserProvider>
  );
}
import careConfig from "@careConfig";
import {
  ArrowLeft,
  CalendarDays,
  Check,
  ChevronDown,
  FolderClosed,
  Home,
  User,
} from "lucide-react";
import { Link, navigate, usePath } from "raviger";
import { createContext, useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { PatientAvatar } from "@/components/Patient/PatientProfileCard";
import { PatientSwitcherSheet } from "@/components/Patient/PatientSwitcherSheet";

import { Button } from "@/components/ui/button";
import { usePatientContext } from "@/hooks/usePatientUser";

/** How long the "now showing records for X" confirmation stays up. */
const SWITCH_NOTICE_MS = 3000;

/** Lets descendant screens open the shell's shared patient switcher sheet. */
const PatientShellContext = createContext<{
  openSwitcher: () => void;
  canSwitch: boolean;
}>({ openSwitcher: () => {}, canSwitch: false });

const TABS = [
  { key: "home", href: "/patient/home", icon: Home, label: "home" },
  {
    key: "visits",
    href: "/patient/visits",
    icon: CalendarDays,
    label: "visits",
  },
  {
    key: "records",
    href: "/patient/records",
    icon: FolderClosed,
    label: "records",
  },
  { key: "profile", href: "/patient/profile", icon: User, label: "profile" },
] as const;

/** `Anitha Ravindran` → `Anitha R.` so the header chip stays on one line. */
function abbreviateName(name: string): string {
  const parts = name.trim().split(/\s+/);
  if (parts.length < 2) {
    return parts[0] ?? "";
  }
  return `${parts[0]} ${parts[parts.length - 1][0]}.`;
}

interface PatientAppShellProps {
  children: React.ReactNode;
  title?: string;
  /** Renders a back affordance instead of the tab bar's implicit navigation. */
  backTo?: string;
  /** Detail screens hide the tab bar so the page owns the full height. */
  hideTabs?: boolean;
  /** Trailing header content, e.g. a download action on detail screens. */
  headerAction?: React.ReactNode;
  /** Underline tabs rendered inside the header — use `PatientHeaderTabs`. */
  headerTabs?: React.ReactNode;
}

/**
 * The section switcher used by Records and Visits. Lives here so both screens
 * share one implementation and stay visually identical.
 */
export function PatientHeaderTabs<T extends string>({
  tabs,
  value,
  onChange,
}: {
  tabs: { key: T; label: string }[];
  value: T;
  onChange: (key: T) => void;
}) {
  return (
    <div className="flex gap-6 px-4">
      {tabs.map((tab) => (
        <button
          key={tab.key}
          type="button"
          onClick={() => onChange(tab.key)}
          aria-current={value === tab.key ? "page" : undefined}
          className={cn(
            "-mb-px flex min-h-11 items-center border-b-[2.5px] pb-2.5 text-sm transition-colors",
            value === tab.key
              ? "border-primary-700 font-bold text-primary-700"
              : "border-transparent font-semibold text-gray-600 hover:text-gray-900",
          )}
        >
          {tab.label}
        </button>
      ))}
    </div>
  );
}

export function PatientAppShell({
  children,
  title,
  backTo,
  hideTabs,
  headerAction,
  headerTabs,
}: PatientAppShellProps) {
  const { t } = useTranslation();
  const path = usePath();
  const { selectedPatient, patients } = usePatientContext();

  const [switcherOpen, setSwitcherOpen] = useState(false);
  const [switchedTo, setSwitchedTo] = useState<string | null>(null);

  useEffect(() => {
    if (!switchedTo) {
      return;
    }
    const timer = setTimeout(() => setSwitchedTo(null), SWITCH_NOTICE_MS);
    return () => clearTimeout(timer);
  }, [switchedTo]);

  const canSwitch = (patients?.length ?? 0) > 1;

  const switcherChip = selectedPatient && (
    <button
      type="button"
      onClick={() => setSwitcherOpen(true)}
      disabled={!canSwitch}
      className={cn(
        "relative flex items-center rounded-full border border-gray-200 bg-gray-50",
        "after:absolute after:inset-x-0 after:-inset-y-1 after:content-['']",
        "min-h-11 gap-2 py-1.5 pl-1.5 pr-3",
        canSwitch && "hover:border-gray-300",
      )}
    >
      <PatientAvatar
        name={selectedPatient.name}
        active
        className="size-6 text-xs"
      />
      <span className="text-sm font-bold text-gray-900">
        {abbreviateName(selectedPatient.name)}
      </span>
      {canSwitch && (
        <ChevronDown className="text-gray-600 size-3.5" strokeWidth={2.2} />
      )}
    </button>
  );

  const tabBar = (
    <>
      {TABS.map((tab) => {
        const isActive = path?.startsWith(tab.href);
        const Icon = tab.icon;
        return (
          <Link
            key={tab.key}
            href={tab.href}
            className={cn(
              "flex flex-col items-center justify-center gap-1 transition-colors",
              isActive
                ? "text-primary-700"
                : "text-gray-400 hover:text-gray-600",
            )}
            aria-current={isActive ? "page" : undefined}
          >
            <Icon className="size-5" strokeWidth={1.9} />
            <span
              className={cn(
                "text-[10px]",
                isActive ? "font-bold" : "font-semibold",
              )}
            >
              {t(tab.label)}
            </span>
          </Link>
        );
      })}
    </>
  );

  // Desktop navigation
  const sideNav = (
    <aside className="sticky top-0 hidden h-dvh w-60 shrink-0 flex-col border-r border-gray-200 bg-white px-3 py-2 lg:flex">
      <Link
        href="/patient/home"
        aria-label={t("care")}
        className="mb-6 px-3 py-1"
      >
        <img
          src={careConfig.mainLogo?.dark}
          alt={t("care")}
          className="h-8 w-auto"

